sys_script_include.script:
var MedicationCheckUtils = Class.create();
MedicationCheckUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkAvailability: function() {
        // Get the medication name from the GlideAjax request
        var medicationName = this.getParameter("sysparm_medname");

        // Ensure input is valid
        if (!medicationName)
            return 'false';

        // Query the medication inventory table
        var medication = new GlideRecord("u_medication_inventory");
        medication.addQuery("u_medication_name", medicationName.toUpperCase());
        medication.query();

        // If medication found, return 'true' (must be a string)
        if (medication.next()) {
            return 'true';
        }

        // If not found
        return 'false';
    },

    type: 'MedicationCheckUtils'
});
